function buildChatRequestMessageList({
  systemPrompt = "",
  baseSessionMessages = [],
  contextCount = 20,
  userText = "",
  userImages = [],
}) {
  const boundedHistoryMessages = (Array.isArray(baseSessionMessages)
    ? baseSessionMessages
    : []
  )
    .filter(
      (historyMessage) =>
        historyMessage?.status !== "pending" &&
        (historyMessage?.role === "user" || historyMessage?.role === "assistant"),
    )
    .slice(-Math.max(0, Number(contextCount) || 20));
  const requestMessageList = [];

  if (systemPrompt && String(systemPrompt).trim()) {
    requestMessageList.push({
      role: "system",
      content: String(systemPrompt).trim(),
    });
  }

  boundedHistoryMessages.forEach((historyMessage) => {
    if (historyMessage.role === "assistant") {
      const resolvedAssistantJsonPrompt = resolveMessageJsonPromptText(historyMessage);
      const assistantTextWithoutJsonBlocks = stripJsonBlocks(
        String(historyMessage.text || ""),
      );
      const assistantRequestContent = resolvedAssistantJsonPrompt
        ? `${
            assistantTextWithoutJsonBlocks
              ? `${assistantTextWithoutJsonBlocks}

`
              : ""
          }\`\`\`json
${resolvedAssistantJsonPrompt}
\`\`\``
        : String(historyMessage.text || "");
      requestMessageList.push({
        role: "assistant",
        content: assistantRequestContent,
      });
      return;
    }

    requestMessageList.push({
      role: "user",
      content: buildOpenAiImageContent(
        String(historyMessage.text || ""),
        Array.isArray(historyMessage.images) ? historyMessage.images : [],
      ),
    });
  });

  requestMessageList.push({
    role: "user",
    content: buildOpenAiImageContent(userText, userImages),
  });

  return requestMessageList;
}

