const CHAT_LOG_TYPE_REGEX = /聊天|chat/;
const IMAGE_LOG_TYPE_REGEX = /跑图|图像|图片|image|绘图|生成图/;
const TASK_PHASE_REGEX = /发送|开始|处理中|连接中|重连中|验证中/;
const SUCCESS_PHASE_REGEX = /返回|成功|完成|通过/;
const TASK_DOMAIN_REGEX = /聊天请求|跑图请求|回传画布/;
const INFRA_DOMAIN_REGEX =
  /插件连接|插件日志|回传测试|取图桥接|图片处理|聊天 API|跑图 API/;
const STATE_CHANGE_PHASE_REGEX = /状态变更|配置校验失败/;
const CONST_MINI_STATUS_MAX_LENGTH = 7;

const consoleLogTypeLabelMap = Object.freeze({
  system: "系统",
  chat: "聊天",
  image: "跑图",
  bridge: "桥接",
  dev: "开发",
});
const DEFAULT_MINI_STATUS_LABEL = "系统就绪";
const DEFAULT_MINI_STATUS_TIP = "点击展开大控制台查看详细日志。";

function normalizeConsoleLogType(logType) {
  const normalizedLogType = String(logType || "")
    .trim()
    .toLowerCase();
  if (!normalizedLogType || normalizedLogType === "api") {
    return "system";
  }
  return normalizedLogType;
}

function resolveConsoleLogType({
  requestedType = "system",
  domain = "",
  phase = "",
  message = "",
} = {}) {
  const normalizedRequestedType = String(requestedType || "")
    .trim()
    .toLowerCase();
  if (normalizedRequestedType !== "api") {
    return normalizeConsoleLogType(normalizedRequestedType);
  }

  const resolveSourceText = `${String(domain || "")} ${String(phase || "")} ${String(message || "")}`.toLowerCase();
  if (CHAT_LOG_TYPE_REGEX.test(resolveSourceText)) {
    return "chat";
  }
  if (IMAGE_LOG_TYPE_REGEX.test(resolveSourceText)) {
    return "image";
  }
  return "system";
}

function resolveConsoleLogTypeLabel(logType) {
  const normalizedLogType = normalizeConsoleLogType(logType);
  return (
    consoleLogTypeLabelMap[normalizedLogType] || normalizedLogType || "系统"
  );
}

function migratePersistedConsoleLogFilters(
  persistedLogFilters,
  allowedLogFilterKeys = [],
) {
  const allowedKeySet = new Set(
    Array.isArray(allowedLogFilterKeys) ? allowedLogFilterKeys : [],
  );
  if (!Array.isArray(persistedLogFilters)) {
    return [];
  }

  const migratedLogFilterKeys = persistedLogFilters
    .flatMap((rawLogFilterKey) => {
      const normalizedFilterKey = String(rawLogFilterKey || "")
        .trim()
        .toLowerCase();
      if (normalizedFilterKey === "api") {
        return ["chat", "image"];
      }
      return [normalizedFilterKey];
    })
    .map((rawFilterKey) => normalizeConsoleLogType(rawFilterKey))
    .filter((normalizedFilterKey) => {
      if (allowedKeySet.size === 0) {
        return true;
      }
      return allowedKeySet.has(normalizedFilterKey);
    });

  return Array.from(new Set(migratedLogFilterKeys));
}

function resolveLifecycleState(logLevel = "", phaseText = "") {
  const normalizedLevel = String(logLevel || "")
    .trim()
    .toLowerCase();
  const normalizedPhaseText = String(phaseText || "").trim();
  if (normalizedLevel === "error") return "error";
  if (normalizedLevel === "warn") return "warn";
  if (TASK_PHASE_REGEX.test(normalizedPhaseText)) return "running";
  if (SUCCESS_PHASE_REGEX.test(normalizedPhaseText)) return "success";
  return "info";
}

function buildApiLifecycleContext({
  level = "info",
  domain = "",
  phase = "",
  message = "",
  startedAt = 0,
  endedAt = 0,
} = {}) {
  const domainText = String(domain || "").trim();
  const phaseText = String(phase || "").trim();
  const domainPhaseText = [domainText, phaseText].filter(Boolean).join(" ");
  const messageText = String(message || "").trim();
  const domainPhaseCompact = domainPhaseText.replace(/\s+/g, "");
  const messageCompact = messageText.replace(/\s+/g, "");
  const summaryBaseText = domainPhaseText
    ? messageText && messageCompact.startsWith(domainPhaseCompact)
      ? messageText
      : `${domainPhaseText}${messageText ? `：${messageText}` : ""}`
    : messageText;

  const startedAtMs =
    Number.isFinite(startedAt) && startedAt > 0 ? Math.floor(startedAt) : 0;
  const hasDurationMetric =
    Number.isFinite(startedAt) &&
    Number.isFinite(endedAt) &&
    endedAt >= startedAt &&
    startedAt > 0;
  const durationSuffixText = hasDurationMetric
    ? `（耗时 ${Math.round(endedAt - startedAt)}ms）`
    : "";

  const lifecycleState = resolveLifecycleState(level, phaseText);
  const normalizedLevel = String(level || "")
    .trim()
    .toLowerCase();
  const finalLifecycleState = hasDurationMetric
    ? normalizedLevel === "error"
      ? "error"
      : normalizedLevel === "warn"
        ? "warn"
        : "success"
    : lifecycleState;

  const isTaskDomain = TASK_DOMAIN_REGEX.test(domainText);
  const isInfraDomain = INFRA_DOMAIN_REGEX.test(domainText);
  const isStateChangePhase = STATE_CHANGE_PHASE_REGEX.test(phaseText);

  return {
    domainText,
    phaseText,
    summaryText: `${summaryBaseText}${durationSuffixText}`,
    lifecycleState,
    finalLifecycleState,
    shouldEmitTaskStart:
      TASK_PHASE_REGEX.test(phaseText) && !hasDurationMetric && startedAtMs > 0,
    shouldEmitTaskEnd: hasDurationMetric && startedAtMs > 0,
    shouldUseTaskPrefix: isTaskDomain && !isInfraDomain && !isStateChangePhase,
  };
}

