async function fetchWithTimeout(
  requestUrl,
  requestOptions = {},
  timeoutMs = 8e3,
) {
  const timeoutAbortController = new AbortController();
  const timeoutTimerHandle = setTimeout(
    () => timeoutAbortController.abort(),
    Math.max(1500, Number(timeoutMs) || 8e3),
  );
  try {
    return await fetch(requestUrl, {
      ...requestOptions,
      signal: timeoutAbortController.signal,
    });
  } catch (fetchError) {
    throw fetchError?.name === "AbortError"
      ? new Error(
          `请求超时（>${Math.round(Math.max(1500, Number(timeoutMs) || 8e3) / 1e3)}s）`,
        )
      : fetchError;
  } finally {
    clearTimeout(timeoutTimerHandle);
  }
}

async function parseFetchResponse(httpResponse) {
  const responseTextRaw = await httpResponse.text();
  const responseContentType = String(
    httpResponse.headers.get("content-type") || "",
  ).toLowerCase();
  let responseJsonValue = null;
  if (responseContentType.includes("application/json")) {
    try {
      responseJsonValue = responseTextRaw ? JSON.parse(responseTextRaw) : {};
    } catch (ignoredError) {
      reportIgnoredProviderRuntimeError("app/empty-catch", ignoredError);
      responseJsonValue = null;
    }
  }
  return {
    status: Number(httpResponse.status) || 0,
    ok: !!httpResponse.ok,
    contentType: responseContentType,
    raw: responseTextRaw,
    data: responseJsonValue,
  };
}

function normalizeChatApiConfig(rawChatApiConfigInput) {
  const normalizedChatApiConfig = {
    ...rawChatApiConfigInput,
  };
  const parseNumberOrFallback = (valueCandidate, fallbackValue) => {
    const parsedNumber = Number(valueCandidate);
    return Number.isFinite(parsedNumber) ? parsedNumber : fallbackValue;
  };
  normalizedChatApiConfig.timeoutMs = Math.max(
    CONST_TIMEOUT_MIN_MS,
    parseNumberOrFallback(
      normalizedChatApiConfig.timeoutMs,
      defaultChatApiConfig.timeoutMs,
    ),
  );
  normalizedChatApiConfig.contextCount = Math.max(
    CONST_CONTEXT_COUNT_MIN,
    Math.min(
      CONST_CONTEXT_COUNT_MAX,
      Math.floor(
        parseNumberOrFallback(
          normalizedChatApiConfig.contextCount,
          defaultChatApiConfig.contextCount,
        ),
      ),
    ),
  );
  normalizedChatApiConfig.maxTokens = Math.max(
    CONST_MAX_TOKENS_MIN,
    Math.min(
      CONST_MAX_TOKENS_MAX,
      Math.floor(
        parseNumberOrFallback(
          normalizedChatApiConfig.maxTokens,
          defaultChatApiConfig.maxTokens,
        ),
      ),
    ),
  );
  normalizedChatApiConfig.temperature = Math.max(
    0,
    Math.min(
      2,
      parseNumberOrFallback(
        normalizedChatApiConfig.temperature,
        defaultChatApiConfig.temperature,
      ),
    ),
  );
  normalizedChatApiConfig.topP = Math.max(
    0,
    Math.min(
      1,
      parseNumberOrFallback(
        normalizedChatApiConfig.topP,
        defaultChatApiConfig.topP,
      ),
    ),
  );
  normalizedChatApiConfig.presencePenalty = Math.max(
    -2,
    Math.min(
      2,
      parseNumberOrFallback(
        normalizedChatApiConfig.presencePenalty,
        defaultChatApiConfig.presencePenalty,
      ),
    ),
  );
  normalizedChatApiConfig.frequencyPenalty = Math.max(
    -2,
    Math.min(
      2,
      parseNumberOrFallback(
        normalizedChatApiConfig.frequencyPenalty,
        defaultChatApiConfig.frequencyPenalty,
      ),
    ),
  );
  normalizedChatApiConfig.baseUrl = String(
    normalizedChatApiConfig.baseUrl || "",
  ).trim();
  normalizedChatApiConfig.apiKey = String(
    normalizedChatApiConfig.apiKey || "",
  ).trim();
  normalizedChatApiConfig.model = String(
    normalizedChatApiConfig.model || "",
  ).trim();
  normalizedChatApiConfig.systemPrompt = String(
    normalizedChatApiConfig.systemPrompt || "",
  );
  return normalizedChatApiConfig;
}

function validateChatApiConfig(
  rawChatApiConfig,
  { requireAuth = true } = {},
) {
  const chatConfigErrors = [];
  if (!rawChatApiConfig.baseUrl) chatConfigErrors.push("聊天地址未填写");
  if (requireAuth && !rawChatApiConfig.apiKey) chatConfigErrors.push("聊天 Key 未填写");
  if (!rawChatApiConfig.model) chatConfigErrors.push("聊天模型未填写");
  if (rawChatApiConfig.timeoutMs < CONST_TIMEOUT_MIN_MS) {
    chatConfigErrors.push("超时时间不能小于 5000ms");
  }
  if (
    rawChatApiConfig.contextCount < CONST_CONTEXT_COUNT_MIN ||
    rawChatApiConfig.contextCount > CONST_CONTEXT_COUNT_MAX
  ) {
    chatConfigErrors.push("上下文条数必须在 1-50");
  }
  if (
    rawChatApiConfig.maxTokens < CONST_MAX_TOKENS_MIN ||
    rawChatApiConfig.maxTokens > CONST_MAX_TOKENS_MAX
  ) {
    chatConfigErrors.push("最大回复 tokens 必须在 1-16384");
  }
  if (rawChatApiConfig.temperature < 0 || rawChatApiConfig.temperature > 2) {
    chatConfigErrors.push("temperature 必须在 0-2");
  }
  if (rawChatApiConfig.topP < 0 || rawChatApiConfig.topP > 1) {
    chatConfigErrors.push("top_p 必须在 0-1");
  }
  if (
    rawChatApiConfig.presencePenalty < -2 ||
    rawChatApiConfig.presencePenalty > 2
  ) {
    chatConfigErrors.push("presence_penalty 必须在 -2 到 2");
  }
  if (
    rawChatApiConfig.frequencyPenalty < -2 ||
    rawChatApiConfig.frequencyPenalty > 2
  ) {
    chatConfigErrors.push("frequency_penalty 必须在 -2 到 2");
  }
  return chatConfigErrors;
}

function validateImageApiConfig(
  rawImageApiConfig,
  { requireAuth = true } = {},
) {
  const imageConfigErrors = [];
  const normalizedImageBaseUrl = String(rawImageApiConfig?.baseUrl || "").trim();
  const normalizedImageApiKey = String(rawImageApiConfig?.apiKey || "").trim();
  const normalizedImageModel = String(rawImageApiConfig?.model || "").trim();
  const normalizedImageTimeoutMs = Number(rawImageApiConfig?.timeoutMs);

  if (!normalizedImageBaseUrl) imageConfigErrors.push("跑图地址未填写");
  if (requireAuth && !normalizedImageApiKey) imageConfigErrors.push("跑图 Key 未填写");
  if (!normalizedImageModel) imageConfigErrors.push("跑图模型未填写");
  if (
    Number.isFinite(normalizedImageTimeoutMs) &&
    normalizedImageTimeoutMs < CONST_TIMEOUT_MIN_MS
  ) {
    imageConfigErrors.push("跑图超时不能小于 5000ms");
  }
  return imageConfigErrors;
}

function normalizeUserFacingErrorMessage(rawErrorInput) {
  const rawErrorText = String(rawErrorInput || "请求失败");
  const extractedRequestId =
    rawErrorText.match(/request id[:：]\s*([^\s)]+)/i)?.[1] || "";
  const hasRequestIdTag = /request id[:：]/i.test(rawErrorText);
  const requestIdSuffix =
    extractedRequestId && !hasRequestIdTag
      ? `（request id: ${extractedRequestId}）`
      : "";

  return rawErrorText === "abort" ||
    rawErrorText === "aborted" ||
    rawErrorText.includes("已停止生成")
    ? "已停止生成"
    : rawErrorText.includes("chat_config_incomplete")
      ? "聊天配置不完整，请先填写地址/Key/模型"
      : rawErrorText.includes("chat_busy")
        ? "当前已有生成任务，请先停止或等待完成"
        : /target_document_not_found|target_document_required/i.test(rawErrorText)
          ? "记录画布未命中，请在弹窗中选择已打开画布后继续导入。"
          : rawErrorText.includes("Failed to fetch")
            ? "网络连接失败，请检查地址或代理设置"
            : /ratio or price not set|倍率或价格未配置/i.test(rawErrorText)
              ? "当前模型计费未开通，请切换到可用模型后重试（服务端返回：ratio or price not set）。"
              : /无可用渠道|no available channel/i.test(rawErrorText)
                ? `当前模型在服务端分组中无可用渠道，请切换模型或分组后重试。${requestIdSuffix}`.trim()
                : /service unavailable|http 503/i.test(rawErrorText)
                  ? `服务端暂时不可用（503），请稍后重试或切换服务商。${requestIdSuffix}`.trim()
                  : rawErrorText;
}
